const W = api.W, H = api.H, N = api.N;
const sp = api.layer('species');
const age = api.layer('age');
const BASE = [null, [255, 196, 60], [70, 190, 255], [255, 85, 140], [130, 245, 100]];
const NAMES = ['', 'Gold', 'Azure', 'Rose', 'Lime'];
// palette[s][lvl] where lvl 0..7: 0 = newborn (bright), 7 = old (deeper)
const PAL = [];
for (let s = 0; s < 5; s++) {
  PAL.push([]);
  for (let l = 0; l < 8; l++) {
    if (!BASE[s]) { PAL[s].push([60, 200, 120]); continue; }
    const b = BASE[s];
    const t = l < 3 ? (3 - l) / 3 * 0.55 : 0;           // whiten young
    const d = l >= 3 ? 1 - (l - 3) * 0.08 : 1;           // darken old
    PAL[s].push([
      Math.round((b[0] + (255 - b[0]) * t) * d),
      Math.round((b[1] + (255 - b[1]) * t) * d),
      Math.round((b[2] + (255 - b[2]) * t) * d)
    ]);
  }
}

// assign tribes to unassigned live cells (quadrants)
for (let i = 0; i < N; i++) {
  if (game.alive[i] && !sp[i]) {
    const x = i % W, y = (i / W) | 0;
    sp[i] = 1 + (x >= 64 ? 1 : 0) + (y >= 40 ? 2 : 0);
  }
}

const prev = new Uint8Array(N);
const cnt = new Int32Array(5);
const pop = [0, 0, 0, 0, 0];

function majority(i) {
  const x = i % W, y = (i / W) | 0;
  cnt[1] = cnt[2] = cnt[3] = cnt[4] = 0;
  for (let dy = -1; dy <= 1; dy++) {
    const yy = (y + dy + H) % H;
    for (let dx = -1; dx <= 1; dx++) {
      if (!dx && !dy) continue;
      const j = yy * W + (x + dx + W) % W;
      if (prev[j]) { const s = sp[j]; if (s >= 1 && s <= 4) cnt[s]++; }
    }
  }
  let best = 0, bc = 0, ties = 0;
  for (let s = 1; s <= 4; s++) {
    if (cnt[s] > bc) { bc = cnt[s]; best = s; ties = 1; }
    else if (cnt[s] === bc && bc > 0) { ties++; if (api.random() * ties < 1) best = s; }
  }
  return best || (1 + ((api.random() * 4) | 0));
}

api.step(function (g, prevStep) {
  prev.set(g.alive);
  prevStep();
  const next = g.alive;
  pop[1] = pop[2] = pop[3] = pop[4] = 0;
  for (let i = 0; i < N; i++) {
    if (next[i]) {
      if (prev[i] && sp[i]) { if (age[i] < 255) age[i]++; }
      else { sp[i] = majority(i); age[i] = 0; }
      pop[sp[i]]++;
    } else if (sp[i]) { sp[i] = 0; age[i] = 0; }
  }
});

