if (!api.state.init) {
  for (let p = 0; p < 14; p++) {
    const cx = (api.random() * W) | 0, cy = (api.random() * H) | 0;
    for (let dy = -4; dy <= 4; dy++) for (let dx = -4; dx <= 4; dx++) {
      if (dx * dx + dy * dy > 16) continue;
      const j = api.idx(cx + dx, cy + dy);
      if (food[j] < 200) food[j] = 200;
    }
  }
  api.state.init = true;
}
if (!api.shared.raids) api.shared.raids = { gold: 0, azure: 0, rose: 0, lime: 0 };
const RKEY = ['', 'gold', 'azure', 'rose', 'lime'];

const prev = new Uint8Array(N);
const cnt = new Int32Array(5);
let conversions = 0, sprouts = 0;

function countTribes(arr, i) {
  const x = i % W, y = (i / W) | 0;
  cnt[0] = cnt[1] = cnt[2] = cnt[3] = cnt[4] = 0;
  let n = 0;
  for (let dy = -1; dy <= 1; dy++) {
    const yy = (y + dy + H) % H;
    for (let dx = -1; dx <= 1; dx++) {
      if (!dx && !dy) continue;
      const j = yy * W + (x + dx + W) % W;
      if (arr[j]) { n++; const s = sp[j]; if (s >= 1 && s <= 4) cnt[s]++; }
    }
  }
  return n;
}
function best() {
  let b = 0, bc = 0;
  for (let s = 1; s <= 4; s++) if (cnt[s] > bc) { bc = cnt[s]; b = s; }
  return b || 1;
}

api.step(function (g, prevStep) {
  prev.set(g.alive);
  prevStep();
  const next = g.alive;
  conversions = 0; sprouts = 0;
  for (let i = 0; i < N; i++) {
    if (next[i]) {
      if (food[i] > 0) food[i] = food[i] > 20 ? food[i] - 20 : 0;
    } else if (food[i] >= 160) {
      // fertile sprouting: two parents beside fertile soil
      if (countTribes(prev, i) === 2) {
        next[i] = 1; sp[i] = best(); age[i] = 0; food[i] = 0; sprouts++;
      }
    }
  }
  // border war: outnumbered cells defect
  for (let i = 0; i < N; i++) {
    if (!next[i]) continue;
    const own = sp[i];
    if (own < 1 || own > 4) continue;
    countTribes(next, i);
    for (let s = 1; s <= 4; s++) {
      if (s !== own && cnt[s] >= 3 && cnt[s] > cnt[own] + 1 && api.random() < 0.5) {
        sp[i] = s; age[i] = 0; conversions++; break;
      }
    }
  }
});

