  }
  let dx = Math.sign(shortest(tx - sx, W)) || (api.random() < 0.5 ? -1 : 1);
  let dy = Math.sign(shortest(ty - sy, H)) || (api.random() < 0.5 ? -1 : 1);
  const ox = sx + dx * 5, oy = sy + dy * 5;
