function wrapd(d, L) { d = ((d % L) + L) % L; return d > L / 2 ? d - L : d; }
function foodAt(x, y) { return food[api.idx(x, y)] + food[api.idx(x + 1, y + 1)]; }
function liveAt(x, y, g) {
  return g.alive[api.idx(x, y)] + g.alive[api.idx(x + 1, y)] + g.alive[api.idx(x, y + 1)] + g.alive[api.idx(x + 1, y + 1)];
}
function kill(g, j) { g.alive[j] = 0; sp[j] = 0; age[j] = 0; }

function spawnBeast(g) {
  const B = beasts();
  let x = (api.random() * W) | 0, y = (api.random() * H) | 0;
  for (let k = 0; k < 40; k++) {
    const tx = (api.random() * W) | 0, ty = (api.random() * H) | 0;
    if (foodAt(tx, ty) > 200 && liveAt(tx, ty, g) === 0) { x = tx; y = ty; break; }
  }
  B.push({ id: api.state.nextId++, x: x, y: y, h: (api.random() * 8) | 0, hp: 8, hit: 0, m: 0, who: 0 });
}

function feast(g, b, w) {
  const offs = [[-3, -3], [4, -3], [-3, 4], [4, 4]];
  for (let k = 0; k < offs.length; k++) {
    const ox = b.x + offs[k][0], oy = b.y + offs[k][1];
    for (let dy = 0; dy < 2; dy++) for (let dx = 0; dx < 2; dx++) {
      const j = api.idx(ox + dx, oy + dy);
      g.alive[j] = 1; sp[j] = w; age[j] = 0;
    }
  }
  for (let dy = -4; dy <= 5; dy++) for (let dx = -4; dx <= 5; dx++) {
    if (dx * dx + dy * dy > 22) continue;
    const j = api.idx(b.x + dx, b.y + dy);
    if (!g.alive[j]) food[j] = 255;
  }
}

