    const w = Math.max(0, Math.min(1, b.hp / 14));
    ctx.fillStyle = 'rgba(0,0,0,0.6)'; ctx.fillRect(cx - 9, cy - 14, 18, 3);
    ctx.fillStyle = w > 0.4 ? 'rgb(120,220,90)' : 'rgb(240,80,60)';
    ctx.fillRect(cx - 9, cy - 14, 18 * w, 3);
    if (b.hit > 0 && b.who >= 1 && b.who <= 4) {
      const c = BASE[b.who];
      ctx.strokeStyle = 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',0.8)';
      ctx.lineWidth = 1;
      ctx.beginPath(); ctx.arc(cx, cy, 14, 0, Math.PI * 2); ctx.stroke();
    }
  }
  for (let k = fx.length - 1; k >= 0; k--) {
    const p = fx[k];
    p.t++;
    if (p.t > 24) { fx.splice(k, 1); continue; }
    const a = (1 - p.t / 24).toFixed(2);
    ctx.fillStyle = 'rgba(' + p.c[0] + ',' + p.c[1] + ',' + p.c[2] + ',' + a + ')';
    for (let r = 0; r < 10; r++) {
      const ang = r * Math.PI / 5;
      ctx.fillRect(p.x * px + Math.cos(ang) * p.t * 2 - 2, p.y * px + Math.sin(ang) * p.t * 2 - 2, 4, 4);
    }
  }
});

api.pointer(function (g, ev) {
