  }
  const n = beasts().length;
  return '<div style="font-family:monospace;font-size:12px;margin-top:6px">' +
    '<b>Great Beasts</b> <span style="color:rgb(160,110,70)">●</span> ' + n + ' roaming<br>' +
    'Beasts graze soil, drop dung and trample cells.<br>' +
