    (lastKill ? '<br>Last kill: <b>' + lastKill + '</b>' : '') + '</div>';
});

const W = api.W, H = api.H, N = api.N;
const sp = api.layer('species');
const age = api.layer('age');
const food = api.layer('food');
const NAMES = ['Wild', 'Gold', 'Azure', 'Rose', 'Lime'];
const RKEY = ['', 'gold', 'azure', 'rose', 'lime'];
const BASE = [[170, 170, 160], [255, 196, 60], [70, 190, 255], [255, 85, 140], [130, 245, 100]];
const TNAMES = ['Sun', 'Moon', 'Storm', 'Root', 'Ember'];
const GOAL = 600;
const R = 6;

function wrapd(d, L) { d = ((d % L) + L) % L; return d > L / 2 ? d - L : d; }

if (!Array.isArray(api.state.totems) || api.state.totems.length === 0) {
  const T = [];
  for (let k = 0; k < 5; k++) {
    let bx = 10 + ((api.random() * (W - 20)) | 0), by = 8 + ((api.random() * (H - 16)) | 0);
    for (let tries = 0; tries < 60; tries++) {
      const x = (api.random() * W) | 0, y = (api.random() * H) | 0;
      let ok = true;
      for (let m = 0; m < T.length; m++) {
        const dx = wrapd(T[m].x - x, W), dy = wrapd(T[m].y - y, H);
        if (dx * dx + dy * dy < 30 * 30) { ok = false; break; }
      }
      if (ok) { bx = x; by = y; break; }
    }
    T.push({ x: bx, y: by, o: 0, c: 0, n: k });
  }
  api.state.totems = T;
}
if (!api.shared.dominion || typeof api.shared.dominion !== 'object') api.shared.dominion = { gold: 0, azure: 0, rose: 0, lime: 0 };
if (!api.shared.eras || typeof api.shared.eras !== 'object') api.shared.eras = { gold: 0, azure: 0, rose: 0, lime: 0 };

const cnt = new Int32Array(5);
const fx = [];
let lastEra = '';

function totems() {
  const T = api.state.totems;
  return Array.isArray(T) ? T : [];
}

function plantHome(g, t) {
  const ang = api.random() * Math.PI * 2;
  const r = 4 + api.random() * 3;
  const ox = Math.round(t.x + Math.cos(ang) * r), oy = Math.round(t.y + Math.sin(ang) * r);
  // need clear surroundings so the block stays a still life
  for (let dy = -1; dy <= 2; dy++) for (let dx = -1; dx <= 2; dx++) {
    const j = api.idx(ox + dx, oy + dy);
    if (g.alive[j] && sp[j] !== t.o) return;
  }
  for (let dy = 0; dy < 2; dy++) for (let dx = 0; dx < 2; dx++) {
    const j = api.idx(ox + dx, oy + dy);
    g.alive[j] = 1; sp[j] = t.o; age[j] = 0;
  }
  if (fx.length < 20) fx.push({ x: ox + 1, y: oy + 1, t: 0, c: BASE[t.o] });
}

api.afterTick(function (g) {
  const T = totems();
  const D = api.shared.dominion || (api.shared.dominion = { gold: 0, azure: 0, rose: 0, lime: 0 });
  for (let k = 0; k < T.length; k++) {
    const t = T[k];
    if (!t || typeof t.x !== 'number' || typeof t.y !== 'number') continue;
    t.o = t.o | 0; if (t.o < 0 || t.o > 4) t.o = 0;
    if (!isFinite(t.c)) t.c = 0;
    if ((g.tick + k) % 4 === 0) {
      cnt[1] = cnt[2] = cnt[3] = cnt[4] = 0;
      for (let dy = -R; dy <= R; dy++) for (let dx = -R; dx <= R; dx++) {
        if (dx * dx + dy * dy > R * R + 2) continue;
        const j = api.idx(t.x + dx, t.y + dy);
        if (g.alive[j]) { const s = sp[j]; if (s >= 1 && s <= 4) cnt[s]++; }
      }
      let w = 0, c = 0;
      for (let s = 1; s <= 4; s++) if (cnt[s] > c) { c = cnt[s]; w = s; }
      if (w && c >= 3) {
        if (t.o === w) t.c = Math.min(100, t.c + c * 0.4);
        else {
          const ownC = t.o ? cnt[t.o] : 0;
          t.c -= Math.max(0.5, (c - ownC) * 0.7);
          if (t.c <= 0) {
            const was = t.o;
            t.o = w; t.c = 8;
            api.toast(NAMES[w] + ' claims the Totem of ' + (TNAMES[t.n | 0] || '?') + (was ? ' from ' + NAMES[was] + '!' : '!'));
            if (fx.length < 20) fx.push({ x: t.x, y: t.y, t: 0, c: BASE[w], big: 1 });
          }
        }
      } else if (t.o && c === 0) {
        t.c = Math.max(1, t.c - 0.2);
      }
    }
    if (t.o) {
      // enrich soil
      if (g.tick % 3 === 0) {
        const a = api.random() * Math.PI * 2, r = api.random() * R;
        const j = api.idx(Math.round(t.x + Math.cos(a) * r), Math.round(t.y + Math.sin(a) * r));
        if (!g.alive[j]) food[j] = 240;
      }
      if ((g.tick + k * 9) % 45 === 0 && t.c > 20) plantHome(g, t);
    }
  }
  if (g.tick % 10 === 0) {
    for (let k = 0; k < T.length; k++) {
      const o = T[k] && T[k].o;
      if (o >= 1 && o <= 4) D[RKEY[o]] = (D[RKEY[o]] | 0) + 1;
    }
    for (let s = 1; s <= 4; s++) {
      if ((D[RKEY[s]] | 0) >= GOAL) {
        const E = api.shared.eras || (api.shared.eras = { gold: 0, azure: 0, rose: 0, lime: 0 });
        E[RKEY[s]] = (E[RKEY[s]] | 0) + 1;
        lastEra = NAMES[s];
        api.toast('The Era of ' + NAMES[s] + ' is proclaimed! A new age begins.');
        D.gold = 0; D.azure = 0; D.rose = 0; D.lime = 0;
        for (let k = 0; k < T.length; k++) if (T[k] && T[k].o) T[k].c = Math.min(T[k].c, 30);
        break;
      }
    }
  }
});

api.draw(function (ctx, g, px) {
  const Wp = W * px, Hp = H * px;
  const phase = (g.tick % 720) / 720;
  const light = 0.5 + 0.5 * Math.cos(phase * Math.PI * 2);
  const dark = (1 - light) * 0.5;
  if (dark > 0.01) {
    ctx.fillStyle = 'rgba(4,6,28,' + dark.toFixed(3) + ')';
    ctx.fillRect(0, 0, Wp, Hp);
  }
  const T = totems();
  for (let k = 0; k < T.length; k++) {
    const t = T[k];
    if (!t || typeof t.x !== 'number') continue;
    const c = BASE[t.o | 0] || BASE[0];
    const cx = t.x * px + px / 2, cy = t.y * px + px / 2;
    const pulse = 0.5 + 0.5 * Math.sin(g.tick * 0.15 + k);
    // glow
    for (let r = 3; r >= 1; r--) {
      ctx.fillStyle = 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + ((0.05 + dark * 0.12) * (4 - r) * 0.5).toFixed(3) + ')';
      ctx.beginPath(); ctx.arc(cx, cy, (R * px) * r / 3 + pulse * 2, 0, Math.PI * 2); ctx.fill();
    }
    // influence ring
    ctx.strokeStyle = 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',0.35)';
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.arc(cx, cy, R * px + 3, 0, Math.PI * 2); ctx.stroke();
    // hold arc
    if (t.o) {
      ctx.strokeStyle = 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',0.95)';
      ctx.lineWidth = 3;
      ctx.beginPath(); ctx.arc(cx, cy, R * px + 3, -Math.PI / 2, -Math.PI / 2 + Math.PI * 2 * Math.max(0, Math.min(1, t.c / 100))); ctx.stroke();
    }
    // pillar
    ctx.fillStyle = 'rgba(0,0,0,0.4)';
    ctx.beginPath(); ctx.ellipse(cx + 1, cy + 8, 7, 3, 0, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = 'rgb(110,104,96)';
    ctx.fillRect(cx - 4, cy - 8, 8, 16);
    ctx.fillStyle = 'rgb(150,142,130)';
    ctx.fillRect(cx - 4, cy - 8, 3, 16);
    ctx.fillStyle = 'rgb(60,56,52)';
    ctx.fillRect(cx - 2, cy - 4, 4, 2);
    ctx.fillRect(cx - 2, cy + 1, 4, 2);
    // flame
    const fh = 5 + pulse * 3;
    ctx.fillStyle = 'rgb(' + c[0] + ',' + c[1] + ',' + c[2] + ')';
    ctx.beginPath();
    ctx.moveTo(cx - 4, cy - 8); ctx.lineTo(cx, cy - 8 - fh); ctx.lineTo(cx + 4, cy - 8);
    ctx.closePath(); ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,0.7)';
    ctx.beginPath();
    ctx.moveTo(cx - 1.5, cy - 8); ctx.lineTo(cx, cy - 8 - fh * 0.5); ctx.lineTo(cx + 1.5, cy - 8);
    ctx.closePath(); ctx.fill();
  }
  for (let k = fx.length - 1; k >= 0; k--) {
    const p = fx[k];
    p.t++;
    const life = p.big ? 30 : 16;
    if (p.t > life) { fx.splice(k, 1); continue; }
    const a = (1 - p.t / life).toFixed(2);
    ctx.strokeStyle = 'rgba(' + p.c[0] + ',' + p.c[1] + ',' + p.c[2] + ',' + a + ')';
    ctx.lineWidth = p.big ? 3 : 1.5;
    ctx.beginPath(); ctx.arc(p.x * px, p.y * px, 2 + p.t * (p.big ? 3 : 1), 0, Math.PI * 2); ctx.stroke();
  }
});

api.hud(function (g) {
  const D = api.shared.dominion || {};
  const E = api.shared.eras || {};
  const T = totems();
  let tl = '';
  for (let k = 0; k < T.length; k++) {
    const t = T[k]; if (!t) continue;
    const o = t.o | 0;
    const c = BASE[o] || BASE[0];
    tl += '<span style="color:rgb(' + c.join(',') + ')">▲' + (TNAMES[t.n | 0] || '?') + '</span> ';
  }
  let rows = '';
  for (let s = 1; s <= 4; s++) {
