      '<span style="width:44px;color:rgb(' + BASE[s].join(',') + ')">' + NAMES[s] + '</span>' +
      '<span style="display:inline-block;width:80px;height:6px;background:#222"><span style="display:block;height:6px;width:' + w + 'px;background:rgb(' + BASE[s].join(',') + ')"></span></span>' +
      '<span>' + v + ' ★' + (E[RKEY[s]] | 0) + '</span></div>';
