  return '<div style="font-family:monospace;font-size:12px;margin-top:6px">' +
    '<b>Totems &amp; Eras</b> · ' + tod + '<br>' +
    'Crowd a Totem with your cells to claim it.<br>Held Totems enrich soil and raise homesteads.<br>' +
    tl + '<br>Dominion (first to ' + GOAL + ' wins the Era):' + rows +
    (lastEra ? 'Last Era: <b>' + lastEra + '</b>' : '') + '</div>';
