const W = api.W, H = api.H, N = api.N;
const sp = api.layer('species');
const age = api.layer('age');
const food = api.layer('food');
const fire = api.layer('fire');
const ash = api.layer('ash');
const NAMES = ['', 'Gold', 'Azure', 'Rose', 'Lime'];

const FP = [];
for (let k = 0; k < 8; k++) FP.push([255, 70 + k * 22, 20 + (k & 3) * 10]);
const ASHP = [];
for (let a = 0; a < 256; a++) { const v = 34 + (a >> 3); ASHP.push([v, v - 3, v - 6]); }

let fresh = false;
if (!Array.isArray(api.state.clouds)) { api.state.clouds = []; fresh = true; }
if (typeof api.state.wind !== 'number' || !isFinite(api.state.wind)) api.state.wind = api.random() * Math.PI * 2;
if (!api.state.nid) api.state.nid = 1;
if (typeof api.shared.strikes !== 'number') api.shared.strikes = 0;

function wrapd(d, L) { d = ((d % L) + L) % L; return d > L / 2 ? d - L : d; }
function clouds() {
  let C = api.state.clouds;
  if (!Array.isArray(C)) { C = []; api.state.clouds = C; }
  for (let k = C.length - 1; k >= 0; k--) {
    const c = C[k];
    if (!c || !isFinite(c.x) || !isFinite(c.y) || !isFinite(c.r)) C.splice(k, 1);
  }
  return C;
}
function spawnCloud() {
  const C = clouds();
  C.push({ id: api.state.nid++, x: api.random() * W, y: api.random() * H, r: 6 + api.random() * 5,
    s: api.random() < 0.45 ? 1 : 0, life: 700 + ((api.random() * 700) | 0), ch: (api.random() * 50) | 0, o: 0 });
}
if (clouds().length === 0) { spawnCloud(); spawnCloud(); spawnCloud(); }
if (fresh) api.toast('Storm clouds gather on the horizon...');

const bolts = [];
const ign = new Int32Array(N);
let burning = 0, lastStrike = '';

function strike(g, c) {
  let tx = -1, ty = -1, fb = -1, fy = -1;
  for (let k = 0; k < 30; k++) {
    const a = api.random() * Math.PI * 2, r = api.random() * c.r;
    const x = Math.round(c.x + Math.cos(a) * r), y = Math.round(c.y + Math.sin(a) * r);
    const j = api.idx(x, y);
    if (fb < 0) { fb = x; fy = y; }
    if (g.alive[j] && (!c.o || sp[j] !== c.o)) { tx = x; ty = y; break; }
  }
  if (tx < 0) { tx = fb; ty = fy; }
  if (tx < 0) return;
  let victim = 0;
  for (let dy = -2; dy <= 2; dy++) for (let dx = -2; dx <= 2; dx++) {
    if (dx * dx + dy * dy > 5) continue;
    const j = api.idx(tx + dx, ty + dy);
    if (g.alive[j]) {
      if (c.o && sp[j] === c.o) continue;
      if (!victim) victim = sp[j];
      g.alive[j] = 0; sp[j] = 0; age[j] = 0;
    }
    if (!ash[j]) fire[j] = 14;
  }
  api.shared.strikes = (api.shared.strikes | 0) + 1;
  lastStrike = victim >= 1 && victim <= 4 ? NAMES[victim] : 'the wilds';
  if (bolts.length < 8) bolts.push({ x: ((tx % W) + W) % W, y: ((ty % H) + H) % H, cx: c.x, cy: c.y, t: 0, seed: api.random() * 1000 });
}

api.step(function (g, prevStep) {
  prevStep();
  const next = g.alive;
  for (let i = 0; i < N; i++) {
    if (fire[i] && next[i]) { next[i] = 0; sp[i] = 0; age[i] = 0; }
  }
});

api.afterTick(function (g) {
  const C = clouds();
  api.state.wind += (api.random() - 0.5) * 0.03;
  const wx = Math.cos(api.state.wind) * 0.07, wy = Math.sin(api.state.wind) * 0.045;
  if (C.length < 5 && g.tick % 150 === 0) spawnCloud();
  for (let k = C.length - 1; k >= 0; k--) {
    const c = C[k];
    if (api.state.drag !== c.id) {
      c.x = ((c.x + wx) % W + W) % W;
      c.y = ((c.y + wy) % H + H) % H;
    }
    c.life = (c.life | 0) - 1;
    if (c.life <= 0) { C.splice(k, 1); continue; }
    if (c.s) {
      c.ch = (c.ch || 0) + 0.6 + api.random();
      if (c.ch >= 95) { c.ch = 0; strike(g, c); }
      // light drizzle
      for (let m = 0; m < 3; m++) {
        const a = api.random() * Math.PI * 2, r = api.random() * c.r;
        const j = api.idx(Math.round(c.x + Math.cos(a) * r), Math.round(c.y + Math.sin(a) * r));
        if (!g.alive[j]) { const v = food[j] + 30; food[j] = v > 255 ? 255 : v; }
      }
    } else {
      for (let m = 0; m < 12; m++) {
        const a = api.random() * Math.PI * 2, r = api.random() * c.r;
        const j = api.idx(Math.round(c.x + Math.cos(a) * r), Math.round(c.y + Math.sin(a) * r));
        fire[j] = 0;
        if (ash[j] > 20) ash[j] -= 20;
        if (!g.alive[j]) { const v = food[j] + 45; food[j] = v > 255 ? 255 : v; }
      }
    }
  }
  // fire & ash
  let ni = 0, b = 0;
  const pS = burning > 700 ? 0.04 : 0.2;
  const spread = (g.tick & 1) === 0;
  const ashTick = (g.tick & 1) === 0;
  for (let i = 0; i < N; i++) {
    const f = fire[i];
    if (f) {
      b++;
      food[i] = 0;
      if (g.alive[i]) { g.alive[i] = 0; sp[i] = 0; age[i] = 0; }
      if (spread && ni < N - 4) {
        const x = i % W, y = (i / W) | 0;
        const n0 = y * W + (x + 1) % W, n1 = y * W + (x + W - 1) % W;
        const n2 = ((y + 1) % H) * W + x, n3 = ((y + H - 1) % H) * W + x;
        if (!fire[n0] && !ash[n0] && food[n0] >= 90 && api.random() < pS) ign[ni++] = n0;
        if (!fire[n1] && !ash[n1] && food[n1] >= 90 && api.random() < pS) ign[ni++] = n1;
        if (!fire[n2] && !ash[n2] && food[n2] >= 90 && api.random() < pS) ign[ni++] = n2;
        if (!fire[n3] && !ash[n3] && food[n3] >= 90 && api.random() < pS) ign[ni++] = n3;
      }
      fire[i] = f - 1;
      if (f === 1) ash[i] = 150;
    } else if (ash[i] && ashTick) {
      ash[i]--;
      if (ash[i] === 0 && !g.alive[i]) food[i] = 215;
    }
  }
  for (let k = 0; k < ni; k++) { const j = ign[k]; if (!fire[j]) fire[j] = 12; }
  burning = b;
});

api.color(function (g, i) {
  const f = fire[i];
  if (f) return FP[(f + g.tick + i) & 7];
  if (!g.alive[i] && ash[i]) return ASHP[ash[i]];
  return null;
});

function puff(ctx, x, y, r, px) {
  ctx.beginPath(); ctx.arc(x * px, y * px, r * px, 0, Math.PI * 2); ctx.fill();
}

api.draw(function (ctx, g, px) {
  const phase = (g.tick % 720) / 720;
  const dark = (1 - (0.5 + 0.5 * Math.cos(phase * Math.PI * 2))) * 0.5;
  // fire glow
  if (burning > 0) {
    ctx.fillStyle = 'rgba(255,120,30,' + (0.1 + dark * 0.5).toFixed(3) + ')';
    let drawn = 0;
    for (let i = 0; i < N && drawn < 350; i++) {
      if (fire[i]) {
        drawn++;
        ctx.fillRect((i % W) * px - 3, ((i / W) | 0) * px - 3, px + 6, px + 6);
      }
    }
  }
  const C = clouds();
  for (let k = 0; k < C.length; k++) {
    const c = C[k];
    const fade = Math.min(1, (c.life | 0) / 60);
    const xs = [c.x]; if (c.x < c.r) xs.push(c.x + W); if (c.x > W - c.r) xs.push(c.x - W);
    const ys = [c.y]; if (c.y < c.r) ys.push(c.y + H); if (c.y > H - c.r) ys.push(c.y - H);
    for (let a = 0; a < xs.length; a++) for (let bb = 0; bb < ys.length; bb++) {
      const x = xs[a], y = ys[bb];
      // shadow
      ctx.fillStyle = 'rgba(0,0,0,' + (0.12 * fade).toFixed(3) + ')';
      puff(ctx, x + 2, y + 3, c.r * 0.9, px);
      // rain streaks
      ctx.strokeStyle = c.s ? 'rgba(170,180,220,' + (0.35 * fade).toFixed(2) + ')' : 'rgba(140,190,255,' + (0.55 * fade).toFixed(2) + ')';
      ctx.lineWidth = 1;
