for (let i = 0; i < N; i++) {
  if (rdist[i] <= 4) nl.push(i);
  if (rdist[i] >= 1 && rdist[i] <= 2) bl.push(i);
}
const nearIdx = Int32Array.from(nl);
const bankIdx = Int32Array.from(bl);

function level(t) {
  const p = t % CYCLE;
  if (p >= FLOODLEN) return 0;
  if (p < 40) return 1 + ((p / 10) | 0);
  if (p < 80) return 4;
  return 1 + (((FLOODLEN - 1 - p) / 10) | 0);
}

api.step(function (g, prevStep) {
  prevStep();
  const a = g.alive;
  const L = level(g.tick);
  if (L === 0) {
    for (let k = 0; k < waterIdx.length; k++) {
      const j = waterIdx[k];
      if (water[j] === 1 && a[j]) { a[j] = 0; sp[j] = 0; age[j] = 0; }
    }
  } else {
    for (let k = 0; k < nearIdx.length; k++) {
      const j = nearIdx[k];
      if (rdist[j] <= L && water[j] !== 3 && a[j]) { a[j] = 0; sp[j] = 0; age[j] = 0; }
    }
  }
});

const fishFx = [];
let lastCatch = '';
const cnt = [0, 0, 0, 0, 0];

api.afterTick(function (g) {
  const L = level(g.tick);
  const p = g.tick % CYCLE;
  if (p === 1) api.toast('The rivers burst their banks! Flee the shores!');
  if (p === FLOODLEN) {
    for (let k = 0; k < nearIdx.length; k++) {
      const j = nearIdx[k];
      if (!water[j] && !g.alive[j]) food[j] = 255;
    }
    api.toast('The flood recedes, leaving rich silt.');
  }
  // water quenches fire
  if (L === 0) { for (let k = 0; k < waterIdx.length; k++) { const j = waterIdx[k]; if (water[j] === 1) fire[j] = 0; } }
  else { for (let k = 0; k < nearIdx.length; k++) { const j = nearIdx[k]; if (rdist[j] <= L) fire[j] = 0; } }
  // irrigation
  if (bankIdx.length) {
    for (let m = 0; m < 30; m++) {
      const j = bankIdx[(api.random() * bankIdx.length) | 0];
      if (!g.alive[j] && !fire[j]) { const v = food[j] + 14; food[j] = v > 255 ? 255 : v; }
    }
  }
  // fish jump
  if (g.tick % 12 === 0 && waterIdx.length) {
    const j = waterIdx[(api.random() * waterIdx.length) | 0];
    if (water[j] === 1) {
      const x = j % W, y = (j / W) | 0;
      cnt[1] = cnt[2] = cnt[3] = cnt[4] = 0;
      let tot = 0;
      for (let dy = -3; dy <= 3; dy++) for (let dx = -3; dx <= 3; dx++) {
        const k = api.idx(x + dx, y + dy);
        if (g.alive[k]) { const s = sp[k]; if (s >= 1 && s <= 4) { cnt[s]++; tot++; } }
      }
      let w = 0;
      if (tot > 0) { w = 1; for (let s = 2; s <= 4; s++) if (cnt[s] > cnt[w]) w = s; }
      if (w) {
        const F = api.shared.fish || (api.shared.fish = { gold: 0, azure: 0, rose: 0, lime: 0 });
        F[RKEY[w]] = (F[RKEY[w]] | 0) + 1;
        lastCatch = NAMES[w];
      }
      if (fishFx.length < 16) fishFx.push({ x: x, y: y, t: 0, w: w, d: api.random() < 0.5 ? -1 : 1 });
    }
  }
});

const WP = [];
for (let k = 0; k < 16; k++) {
  const s = 0.5 + 0.5 * Math.sin(k * TAU / 16);
  WP.push([Math.round(25 + 30 * s), Math.round(70 + 45 * s), Math.round(140 + 60 * s)]);
}
const FLOODC = [[60, 85, 110], [55, 80, 105]];
const STONE = [[120, 104, 84], [96, 84, 70]];

api.color(function (g, i) {
  const w = water[i];
  if (w === 1) {
    const x = i % W, y = (i / W) | 0;
    return WP[(x + y * 2 - (g.tick >> 1)) & 15];
  }
  if (w === 3) {
    if (g.alive[i]) return null;
    return STONE[((i % W) + ((i / W) | 0)) & 1];
  }
  const r = rdist[i];
  if (r <= 4 && !g.alive[i]) {
    const L = level(g.tick);
    if (r <= L) return FLOODC[(i + (g.tick >> 2)) & 1];
  }
  return null;
});

api.draw(function (ctx, g, px) {
  for (let k = fishFx.length - 1; k >= 0; k--) {
    const f = fishFx[k];
    f.t++;
    if (f.t > 14) { fishFx.splice(k, 1); continue; }
    const s = f.t / 14;
    const cx = f.x * px + px / 2 + f.d * s * 10, cy = f.y * px + px / 2 - Math.sin(s * Math.PI) * 12;
    ctx.fillStyle = 'rgb(210,225,240)';
    ctx.beginPath(); ctx.ellipse(cx, cy, 3.5, 1.8, f.d * (s - 0.5) * 1.6, 0, TAU); ctx.fill();
    if (f.t > 10 || f.t < 3) {
      ctx.strokeStyle = 'rgba(200,230,255,' + (0.6 * (1 - s)).toFixed(2) + ')';
      ctx.lineWidth = 1;
      ctx.beginPath(); ctx.arc(f.x * px + px / 2, f.y * px + px / 2, 2 + f.t * 0.6, 0, TAU); ctx.stroke();
    }
    if (f.w && f.t > 9) {
      const c = BASE[f.w];
      ctx.fillStyle = 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + (1 - s).toFixed(2) + ')';
      ctx.font = '9px monospace';
      ctx.fillText('+🐟', cx - 6, cy - 4);
    }
  }
});

api.pointer(function (g, ev) {
  if (ev.type !== 'down' || typeof ev.i !== 'number' || ev.i < 0 || ev.i >= N) return undefined;
  if (water[ev.i] !== 1) return undefined;
  const F = api.shared.fish || (api.shared.fish = { gold: 0, azure: 0, rose: 0, lime: 0 });
  if ((F.gold | 0) < 5) { api.toast('Gold needs 5 🐟 to build a bridge (has ' + (F.gold | 0) + ').'); return true; }
  F.gold = (F.gold | 0) - 5;
  const x = ev.i % W, y = (ev.i / W) | 0;
  for (let dy = -2; dy <= 2; dy++) for (let dx = -2; dx <= 2; dx++) {
    if (dx * dx + dy * dy > 5) continue;
    const j = api.idx(x + dx, y + dy);
    if (water[j] === 1) water[j] = 3;
  }
  api.toast('Gold builds a bridge across the river!');
  return true;
});

api.hud(function (g) {
  const t = g && typeof g.tick === 'number' ? g.tick : 0;
  const p = t % CYCLE;
  const F = api.shared.fish || {};
  let rows = '';
  for (let s = 1; s <= 4; s++) rows += '<span style="color:rgb(' + BASE[s].join(',') + ')">' + NAMES[s] + ' ' + (F[RKEY[s]] | 0) + '</span> ';
  const fl = p < FLOODLEN ? '<b style="color:rgb(120,170,255)">🌊 FLOOD! level ' + level(t) + '</b>'
    : 'Next flood in ' + Math.ceil((CYCLE - p) * 0.12) + 's';
  return '<div style="font-family:monospace;font-size:12px;margin-top:6px">' +
    '<b>Rivers &amp; Floods</b> · ' + fl + '<br>' +
    '<span style="color:rgb(60,110,190)">■</span> Water drowns cells and stops fire. ' +
    '<span style="color:rgb(120,104,84)">■</span> Fords let tribes cross.<br>' +
    'Banks grow lush. Floods leave rich silt.<br>' +
    'Shore tribes catch fish 🐟: ' + rows + '<br>' +
    '<b>Click a river</b> with 5 🐟 to build a Gold bridge.' +
    (lastCatch ? '<br>Last catch: <b>' + lastCatch + '</b>' : '') + '</div>';
});
